def check_n(n, limit):
    triples = []
    for a in range(1, limit):
        for b in range(a + 1, limit):
            # c^2(a+b) + c(a^2 + b^2 + 3ab + 1 - 4nab) + (a+b)(ab+1) = 0
            A = a + b
            B = a**2 + b**2 + 3*a*b + 1 - 4*n*a*b
            C = (a + b) * (a*b + 1)

            # Discriminant D = B^2 - 4*A*C
            D = B**2 - 4*A*C
            if D >= 0:
                import math
                sqrt_D = int(math.isqrt(D))
                if sqrt_D * sqrt_D == D:
                    for sign in [-1, 1]:
                        numerator = -B + sign * sqrt_D
                        if numerator > 0 and numerator % (2 * A) == 0:
                            c = numerator // (2 * A)
                            if c > 0 and c != a and c != b:
                                triples.append(tuple(sorted((a, b, c))))
    return sorted(list(set(triples)))

for n in [1, 2, 3, 4, 5, 6, 7]:
    res = check_n(n, 100)
    print(f"n={n}, triples={res}")

